  "settings.clearLibraryV2Hint": "Vymaže index (skladby, alba, interpreti). Spolu s ním se ztratí: obsah playlistů, hodnocení, záložky, oblíbené, ručně sestavené boxy a úpravy alb. Žádný hudební soubor se nesmaže. Těsně předtím se vytvoří záloha databáze. Skenování vrátí jen skladby. Pro obnovení knihovny raději spusťte úplné skenování: zachová boxy i úpravy alb.",
