  "renderer.depthCapNotRate": "Pozor: omezení bitové hloubky neomezuje vzorkovací frekvenci. Soubor 96 kHz/24 bitů se změní na 96 kHz/16 bitů — stále 96 kHz. Pokud váš renderer zvládne nejvýše 48 kHz, nastavte také „Max. frekvence“.",
  "renderer.flacAndWavSplitBySource": "„Vynutit WAV“ platí jen pro zdroje mimo FLAC (ALAC, AAC…) — obchází dekodér ALAC rendereru. Vaše soubory FLAC se dál posílají jako nativní FLAC.",
  "renderer.wav24Unproven": "Žádný test vyhledávání zatím neuspěl: 24 bitů zůstává dostupných, ale nic nepotvrzuje, že je toto zařízení umí přehrát. Stiskněte „Ověřit“ výše.",
  "renderer.wav24Refused": "Test vyhledávání odpověděl: toto zařízení neuvádí audio/L24 ani audio/wav. 24 bitů zůstává zakázáno — jejich odeslání by přehrálo ticho.",
  "renderer.startDelay": "Zpoždění spuštění",
  "renderer.startDelayHint": "Pauza před spuštěním přehrávání, aby si zesilovač DLNA stihl naplnit vyrovnávací paměť (pomáhá, když první sekundy zadrhávají). 0 = výchozí.",
  "renderer.fluxContinu": "Souvislý stream mezi skladbami",
  "renderer.fluxContinuHint": "Pro přehrávače, které špatně navazují dvě po sobě jdoucí skladby: po sobě jdoucí skladby stejného formátu se posílají jako jediný stream WAV bez zpracování. Při první změně formátu se obnoví běžné přehrávání skladba po skladbě.",
