  "renderer.resetCompat": "Resetovat kompatibilitu",
  "renderer.resetCompatHint": "Když tento renderer odmítne příkaz, Tune si zapamatuje podobu příkazu, kterou přijal, a používá ji i po restartu. Reset zajistí, že další skladba začne znovu s úplným příkazem.",
