  "renderer.resetCompatError": "Reset kompatibility se nezdařil.",
  "settings.dlnaCap16bitHint": "Zapněte, pokud hi-res (24 bitů) na tomto rendereru nehraje, zatímco 16 bitů funguje (Ruark R3). Převádí do 16bitového FLAC místo přímého odesílání 24 bitů, které renderer neumí dekódovat.",
  "settings.alacPassthroughHint": "Posílat ALAC do tohoto rendereru beze změny (bit-perfect, bez transkódování do FLAC). Zapněte pouze tehdy, když renderer dekóduje ALAC nativně, jinak nebude žádný zvuk.",
  "settings.aacPassthroughHint": "Posílat AAC do tohoto rendereru beze změny místo transkódování do FLAC. Zdroj je už ztrátový, takže transkódování kvalitu nepřidá — jen zpozdí první zvuk. Zapněte pouze tehdy, když renderer dekóduje AAC nativně, jinak nebude žádný zvuk.",
