  "settings.cloudDisconnected": "Odhlášeno z cloudu",
  "settings.signOutConfirm": "Odhlásit se z účtu Mozaiklabs? Tento server bude od účtu odpojen: jeho online kopie knihovny a sdílení Tune Circle budou odstraněny a funkce Premium poskytované účtem přestanou fungovat (licenční klíč zůstává aktivní). Poté se můžete znovu přihlásit.",
  "settings.licenseRateLimited": "Příliš mnoho pokusů — počkejte minutu a zkuste to znovu.",
