  "settings.telemetry": "Telemetrie",
  "settings.telemetryHint": "Odesílat statistiky používání pro zlepšení Tune: identifikátor instance, verzi, platformu, velikosti knihovny, připojené služby a modely zařízení.",
  "settings.telemetryOffScope": "Vypnutím se zastaví i komunitní sdílení a stahování metadat. Ověřování licence běží dál, takže o Premium nikdy nepřijdete.",
  "settings.communitySync": "Komunitní sdílení metadat",
  "settings.communitySyncHint": "Zapojit se do komunitního obohacování: identifikace MusicBrainz, žánry a tvůrci (skladatel, dirigent, interpreti) sdílené mezi servery Tune. Anonymně — nikdy vaše soubory.",
  "settings.cloudListens": "Posílat můj poslech na můj účet",
  "settings.cloudListensHint": "Přidá poslechy z tohoto serveru na stránku „Můj poslech“ vašeho účtu, spolu s ostatními vašimi servery Tune. U každého poslechu se odesílá: datum, délka, neprůhledný identifikátor profilu, název, interpret, album a, pokud jsou známy, ISRC a identifikátor MusicBrainz. Nikdy cesty k vašim souborům, vaše IP adresa ani názvy zón. Ve výchozím stavu vypnuto.",
  "settings.cloudListensLink": "Zobrazit můj poslech na mozaiklabs.fr",
