  "settings.cloudListensConsentBenefit": "Co tím získáte: stránku „Můj poslech“, která shromažďuje poslechy ze všech vašich serverů Tune, a poslech komunity.",
  "settings.cloudListensConsentSettingsReminder": "Názor můžete kdykoli změnit v Nastavení › Systém.",
  "settings.cloudListensConsentError": "Vaši odpověď se nepodařilo uložit. Zkuste to znovu.",
