  "settings.cloudListensConsentYes": "Ano, sdílet",
  "settings.cloudListensConsentClose": "Zavřít bez odpovědi",
  "settings.communityShare": "Sdílet moje hodnocení a poslechy s komunitou (anonymně)",
  "settings.communityShareHint": "Nezávislé na „Můj poslech“ a ve výchozím stavu vypnuté. Vaše hodnocení alb (bez komentáře) a poslechy, které váš účet obdrží PO zapnutí, se započítávají do veřejných anonymních součtů, zobrazených na stránce alba od tří různých osob. Žádné jednotlivé údaje se nikdy nezobrazují. Vypnutím se váš příspěvek okamžitě odebere.",
  "settings.communityMeasuresReceive": "Přijímat výsledky analýz od komunity",
  "settings.communityMeasuresReceiveHint": "Ve výchozím stavu vypnuto. Pro vaše soubory FLAC si server vyžádá od mozaiklabs.fr hodnoty ReplayGain, dynamického rozsahu a akustické otisky, které už na naprosto stejném signálu naměřily alespoň dvě jiné instalace. Doplňují pouze to, co chybí: vaše tagy a vaše vlastní měření se nikdy nenahrazují. Web dostane jen krátký prefix, nikdy seznam vašich souborů.",
  "settings.communityMeasuresContribute": "Sdílet moje výsledky analýz s komunitou",
  "settings.communityMeasuresContributeHint": "Ve výchozím stavu vypnuto. Server odešle na web pouze měření, která sám provedl na vašich souborech FLAC (ReplayGain, dynamický rozsah, akustický otisk), označená podpisem jejich signálu. Neodesílá se žádná cesta, název, název souboru ani účet: server se identifikuje číslem instalace. Vypnutím se odeslaná data smažou.",
